import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import { createEmployee, updateEmployee } from '../../store/employeeSlice';
import api from '../../api/axios';

const inputStyle = {
  width: '100%', boxSizing: 'border-box',
  border: '1.5px solid #e5e7eb', borderRadius: 10,
  padding: '10px 14px', fontSize: 14, outline: 'none',
  fontFamily: 'inherit', color: '#111827', background: '#fff',
  transition: 'border-color 0.15s',
};

const EmployeeForm = ({ employee, onSubmit, onCancel }) => {
  const dispatch = useDispatch();
  const [loading, setLoading] = useState(false);
  const [departments, setDepartments] = useState([]);
  const [positions, setPositions] = useState([]); // Список должностей
  const [isNewPosition, setIsNewPosition] = useState(false); // Режим ввода новой должности
  const [form, setForm] = useState({
    full_name: '', position: '', department: '', phone: '', email: '',
    role: 'employee', username: '', password: '',
  });

  // Загружаем список отделов и должностей
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [deptsRes, positionsRes] = await Promise.all([
          api.get('/departments/'),
          api.get('/positions/') // Предполагаемый эндпоинт для должностей
        ]);
        setDepartments(deptsRes.data.results || deptsRes.data || []);
        setPositions(positionsRes.data.results || positionsRes.data || []);
      } catch (error) {
        console.error('Ошибка загрузки данных:', error);
        // Если эндпоинт /positions/ не существует, загружаем должности из сотрудников
        if (error.response?.status === 404) {
          try {
            const employeesRes = await api.get('/employees/');
            const employees = employeesRes.data.results || employeesRes.data || [];
            const uniquePositions = [...new Set(employees.map(emp => emp.position).filter(Boolean))];
            setPositions(uniquePositions.map(pos => ({ id: pos, name: pos })));
          } catch (err) {
            console.error('Ошибка загрузки должностей из сотрудников:', err);
          }
        }
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (employee) {
      setForm({
        full_name: employee.full_name || '',
        position: employee.position || '',
        department: employee.department?.id || employee.department || '',
        phone: employee.phone || '',
        email: employee.email || '',
        role: employee.role || 'employee',
        username: '',
        password: '',
      });
    } else {
      setForm({
        full_name: '', position: '', department: '', phone: '', email: '',
        role: 'employee', username: '', password: '',
      });
    }
  }, [employee]);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!form.full_name.trim()) {
      toast.error('Введите ФИО сотрудника');
      return;
    }
    if (!form.position.trim()) {
      toast.error('Введите должность');
      return;
    }
    if (!employee && (!form.username.trim() || !form.password)) {
      toast.error('Для нового сотрудника укажите логин и пароль');
      return;
    }

    setLoading(true);
    try {
      if (employee) {
        const { username, password, ...updateData } = form;
        const payload = {
          ...updateData,
          user_id: employee.user_id || employee.user?.id || employee.user,
          department: updateData.department ? Number(updateData.department) : null,
        };
        
        Object.keys(payload).forEach(key => {
          if (payload[key] === undefined) delete payload[key];
        });
        
        await dispatch(updateEmployee({ id: employee.id, ...payload })).unwrap();
        toast.success('Данные сотрудника обновлены');
      } else {
        const payload = {
          ...form,
          department: form.department ? Number(form.department) : null,
        };
        
        await dispatch(createEmployee(payload)).unwrap();
        toast.success('Сотрудник успешно добавлен');
      }
      onSubmit();
    } catch (err) {
      let errorMessage = 'Ошибка сохранения';
      if (typeof err === 'string') {
        errorMessage = err;
      } else if (err?.user_id?.[0]) {
        errorMessage = `Ошибка с пользователем: ${err.user_id[0]}`;
      } else if (err?.department?.[0]) {
        errorMessage = `Ошибка с отделом: ${err.department[0]}`;
      } else if (err?.detail) {
        errorMessage = err.detail;
      } else if (err?.message) {
        errorMessage = err.message;
      }
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      background: '#fff', borderRadius: 16, padding: 24,
      border: '1px solid #e5e7eb', boxShadow: '0 4px 16px rgba(0,0,0,0.06)', 
      marginBottom: 24,
    }}>
      <h2 style={{ margin: '0 0 20px', fontSize: 17, fontWeight: 700, color: '#111827' }}>
        {employee ? '✏️ Редактирование сотрудника' : '➕ Новый сотрудник'}
      </h2>

      <form onSubmit={handleSubmit}>
        <div style={{ display: 'grid', gap: 14 }}>

          {/* Логин и пароль - только для нового сотрудника */}
          {!employee && (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              <div>
                <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
                  Логин <span style={{ color: '#ef4444' }}>*</span>
                </label>
                <input 
                  name="username" 
                  placeholder="username" 
                  value={form.username}
                  onChange={handleChange} 
                  style={inputStyle}
                  onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                  onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                  required 
                />
              </div>
              <div>
                <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
                  Пароль <span style={{ color: '#ef4444' }}>*</span>
                </label>
                <input 
                  name="password" 
                  type="password" 
                  placeholder="••••••••" 
                  value={form.password}
                  onChange={handleChange} 
                  style={inputStyle}
                  onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                  onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                  required 
                />
              </div>
            </div>
          )}

          {/* ФИО */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
              ФИО <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <input 
              name="full_name" 
              placeholder="Иванов Иван Иванович" 
              value={form.full_name}
              onChange={handleChange} 
              style={inputStyle}
              onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
              onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              required 
            />
          </div>

          {/* Должность - с возможностью ввода новой */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
              Должность <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
              <button
                type="button"
                onClick={() => setIsNewPosition(false)}
                style={{
                  padding: '6px 12px',
                  fontSize: 12,
                  fontWeight: 500,
                  borderRadius: 8,
                  border: isNewPosition ? '1px solid #e5e7eb' : '1px solid #2563eb',
                  background: isNewPosition ? '#fff' : '#2563eb',
                  color: isNewPosition ? '#6b7280' : '#fff',
                  cursor: 'pointer',
                  transition: 'all 0.15s',
                }}
              >
                Выбрать из списка
              </button>
              <button
                type="button"
                onClick={() => setIsNewPosition(true)}
                style={{
                  padding: '6px 12px',
                  fontSize: 12,
                  fontWeight: 500,
                  borderRadius: 8,
                  border: isNewPosition ? '1px solid #2563eb' : '1px solid #e5e7eb',
                  background: isNewPosition ? '#2563eb' : '#fff',
                  color: isNewPosition ? '#fff' : '#6b7280',
                  cursor: 'pointer',
                  transition: 'all 0.15s',
                }}
              >
                ✏️ Ввести новую
              </button>
            </div>
            
            {isNewPosition ? (
              <input
                name="position"
                placeholder="Введите новую должность"
                value={form.position}
                onChange={handleChange}
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                required
              />
            ) : (
              <div style={{ position: 'relative' }}>
                <select
                  name="position"
                  value={form.position}
                  onChange={handleChange}
                  style={{ ...inputStyle, cursor: 'pointer' }}
                  required
                >
                  <option value="">Выберите должность</option>
                  {positions.map(pos => (
                    <option key={pos.id || pos.name} value={pos.name}>
                      {pos.name}
                    </option>
                  ))}
                </select>
                {positions.length === 0 && (
                  <p style={{ margin: '4px 0 0', fontSize: 11, color: '#f59e0b' }}>
                    ⚠️ Нет доступных должностей. Нажмите «Ввести новую»
                  </p>
                )}
              </div>
            )}
          </div>

          {/* Отдел */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
              Отдел
            </label>
            <select
              name="department"
              value={form.department}
              onChange={handleChange}
              style={{ ...inputStyle, cursor: 'pointer' }}
            >
              <option value="">— Без отдела —</option>
              {departments.map(d => (
                <option key={d.id} value={d.id}>
                  {d.name}
                </option>
              ))}
            </select>
          </div>

          {/* Телефон и Email */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
                Телефон
              </label>
              <input 
                name="phone" 
                placeholder="+7 999 000 00 00" 
                value={form.phone}
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              />
            </div>
            <div>
              <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
                Email
              </label>
              <input 
                name="email" 
                type="email" 
                placeholder="example@company.com" 
                value={form.email}
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              />
            </div>
          </div>

          {/* Роль */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: '#6b7280', display: 'block', marginBottom: 5 }}>
              Роль
            </label>
            <select
              name="role"
              value={form.role}
              onChange={handleChange}
              style={{ ...inputStyle, cursor: 'pointer' }}
            >
              <option value="employee">👤 Сотрудник</option>
              <option value="admin">👑 Администратор</option>
            </select>
          </div>

        </div>

        {/* Кнопки */}
        <div style={{ display: 'flex', gap: 10, marginTop: 24 }}>
          <button 
            type="submit" 
            disabled={loading} 
            style={{
              background: loading ? '#93c5fd' : 'linear-gradient(135deg, #2563eb, #1d4ed8)',
              color: '#fff', border: 'none', borderRadius: 10,
              padding: '10px 24px', fontWeight: 600, fontSize: 14,
              cursor: loading ? 'not-allowed' : 'pointer',
              boxShadow: loading ? 'none' : '0 4px 12px rgba(37,99,235,0.3)',
              transition: 'all 0.15s',
            }}
            onMouseEnter={e => {
              if (!loading) {
                e.currentTarget.style.transform = 'translateY(-1px)';
              }
            }}
            onMouseLeave={e => {
              if (!loading) {
                e.currentTarget.style.transform = 'translateY(0)';
              }
            }}
          >
            {loading ? '⏳ Сохранение...' : (employee ? '💾 Сохранить' : '➕ Добавить')}
          </button>
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={loading}
            style={{
              background: '#f3f4f6', color: '#374151', border: 'none',
              borderRadius: 10, padding: '10px 24px', fontWeight: 600, fontSize: 14,
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background 0.15s',
            }}
            onMouseEnter={e => {
              if (!loading) {
                e.currentTarget.style.background = '#e5e7eb';
              }
            }}
            onMouseLeave={e => {
              if (!loading) {
                e.currentTarget.style.background = '#f3f4f6';
              }
            }}
          >
            Отмена
          </button>
        </div>
      </form>
    </div>
  );
};

export default EmployeeForm;
